"""Correct skew Y/Z convention and check native axes before every Engine."""
from run_aircraft_a29 import *

FRAME_CHECK="""
def validate_native_frame(d,n):
    t=(d/(n+'_0000.out')).read_text();m=re.search(r'SKEW SYSTEM SETS.*?VECTORS.*?ORIGIN\\s+1\\s+0\\s+0\\s+0\\s+([^\\n]+)\\n\\s+([^\\n]+)\\n\\s+([^\\n]+)',t,re.S);assert m,'Missing native skew readback'
    axes=np.array([[float(v) for v in line.split()][:3] for line in m.groups()]);expected=np.array([[0,1,0],[-1,0,0],[0,0,1]])
    p=re.search(r'Isolid  Ismstr   Icpre     NPT ICONTROL\\s+(\\d+)\\s+(\\d+)\\s+(\\d+)\\s+(\\d+)\\s+(\\d+)',t);assert p
    flags=list(map(int,p.groups()));checks={'axes':bool(np.allclose(axes,expected,atol=1e-6,rtol=0)),'native_flags':flags==[18,2,3,8,0]};dump(d/'native_frame_gate.json',{'created_utc':now(),'axes_rows':axes.tolist(),'expected_axes_rows':expected.tolist(),'native_flags':flags,'checks':checks,'pass':all(checks.values()),'before_Engine':True});assert all(checks.values()),checks
"""

def main():
    h=harness();assert h['Status']=='PASS';dump(OUT/'harness_before_frame_corrected.json',h);p=OUT/'w1/PATCH_NORMAL_X_N12';assert read(p/'review.json')['checks']['native_full_balance'] and not read(p/'review.json')['checks']['independent_elastic_reference'];assert len(list((OUT/'w1').glob('*/review.json')))==1
    cfg=ROOT/'wtc1_simulation_v8/data/aircraft_a29_frame_corrected.json';target=Path(__file__).with_name('test_aircraft_a29_frame_corrected.py');assert not cfg.exists() and not target.exists();c=read(ROOT/'wtc1_simulation_v8/data/aircraft_a29_auto_strain.json');c.update(revision='w2',declared_utc=now(),parent_configuration_sha256=streamsha(ROOT/'wtc1_simulation_v8/data/aircraft_a29_auto_strain.json'),frame_correction='SKEW/FIX takes Yprime and Zprime, not Xprime and Yprime. w1 actually produced material axes globalZ,globalY,-globalX, so globalX response was E33; wrong-frame native result retained. w2 inputs Yprime=-globalX,Zprime=globalZ, reconstructing Xprime=globalY as originally declared. Full3D tensor, physical volume/density, material card and thresholds unchanged. Native axes and resolved property flags checked before each Engine.');dump(cfg,c);dump(OUT/'frame_corrected_guard.json',{'created_utc':now(),'sha256':streamsha(cfg),'before_new_native_solvers':True});q=OUT/'sources/skew_fix.html';assert not q.exists();u='https://help.altair.com/hwsolvers/rad/topics/solvers/rad/skew_fix_starter_r.htm';q.write_bytes(urllib.request.urlopen(u,timeout=45).read());dump(OUT/'frame_correction_sources.json',{'created_utc':now(),'files':[{'url':u,'path':rel(q),'sha256':streamsha(q),'bytes':q.stat().st_size,'redistribution':'exclude_third_party'}]})
    source=Path(__file__).with_name('test_aircraft_a29_auto_strain.py');s=source.read_text(encoding='utf-8');audit=[]
    for old,new in [('aircraft_a29_auto_strain.json','aircraft_a29_frame_corrected.json'),("OUT/'auto_strain_guard.json'","OUT/'frame_corrected_guard.json'"),("OUT/'w1'","OUT/'w2'"),("OUT/'native_case_summary_w1.json'","OUT/'native_case_summary_w2.json'"),("OUT/'runner_w1_derivation.json'","OUT/'runner_w2_derivation.json'"),("OUT/'review_w1_derivation.json'","OUT/'review_w2_derivation.json'"),("n='A29_W1_3D_'+cid","n='A29_W2_3D_'+cid"),('ff(0,1,0),ff(-1,0,0)','ff(-1,0,0),ff(0,0,1)')]:
        count=s.count(old);assert count>0,old;s=s.replace(old,new);audit.append({'old':old,'new':new,'count':count})
    hook="    ast.parse(s);exec(compile(s,__file__+'::run_one','exec'),globals());p=OUT/'runner_w2_derivation.json'";assert s.count(hook)==1;s=s.replace(hook,"    s=s.replace(\"assert execute(RUNTIME/'engine_win64.exe'\",\"validate_native_frame(d,n);assert execute(RUNTIME/'engine_win64.exe'\")\n"+hook);point="if __name__=='__main__':";assert s.count(point)==1;s=s.replace(point,FRAME_CHECK+'\n'+point);ast.parse(s);target.write_text(s,encoding='utf-8',newline='\n');dump(OUT/'frame_corrected_derivation.json',{'created_utc':now(),'source':rel(source),'source_sha256':streamsha(source),'target':rel(target),'target_sha256':streamsha(target),'changes':audit,'new_native_gate_source':FRAME_CHECK,'material_fields_unchanged':True,'previous_native_solvers_not_rerun':True});print({'A29_w2_declared':True,'wrong_frame_w1_preserved':True,'native_frame_checked_before_Engine':True},flush=True)

if __name__=='__main__':main()
